window.wp = window.wp || {};
(function (wp) {
  if (wp.hooks) return;
  var actions = {}, filters = {};
  wp.hooks = {
    addAction: function (name, namespace, callback, priority) {
      actions[name] = actions[name] || [];
      actions[name].push({ callback: callback, priority: priority || 10 });
    },
    removeAction: function (name, namespace) {
      if (actions[name]) actions[name] = [];
    },
    hasAction: function (name) {
      return !!(actions[name] && actions[name].length);
    },
    doAction: function (name) {
      var args = Array.prototype.slice.call(arguments, 1);
      (actions[name] || []).forEach(function (act) {
        try { act.callback.apply(null, args); } catch (e) {}
      });
    },
    addFilter: function (name, namespace, callback, priority) {
      filters[name] = filters[name] || [];
      filters[name].push({ callback: callback, priority: priority || 10 });
    },
    removeFilter: function (name, namespace) {
      if (filters[name]) filters[name] = [];
    },
    hasFilter: function (name) {
      return !!(filters[name] && filters[name].length);
    },
    applyFilters: function (name, value) {
      var args = Array.prototype.slice.call(arguments, 1);
      return (filters[name] || []).reduce(function (val, f) {
        try { return f.callback.apply(null, [val].concat(args.slice(1))); } catch (e) { return val; }
      }, value);
    }
  };
})(window.wp);
